Context("Fraction-NoDecimals"); Context()->operators->redefine('>',using=>',',from=>'Numeric'); Context()->lists->set('List' => {separator => '>'});
@d = (2..9)[NchooseK(8,5)]; @a = map{Fraction(random_coprime([1..2*$_], [$_]))} (@d); $as = join('\quad', map{'{' . $_->TeX . '}'} (@a)); @b = PGsort(sub{$_[0] > $_[1]}, @a); $bs = join('>', @b);
$comparison = Compute("$bs");
